#include <bits/stdc++.h>
using namespace std;

int main() {
    vector<string> lines;
    string line;
    while (getline(cin, line)) {
        if (!line.empty() && line.back() == '\r') line.pop_back();
        lines.push_back(line);
    }
    int width, p;
    sscanf(lines[0].c_str(), "%d %d", &width, &p);
    size_t idx = 1;
    string border(width + 2, '*'), out = border + "\n";
    for (int k = 0; k < p; k++) {
        char align[16];
        int count;
        sscanf(lines[idx++].c_str(), "%15s %d", align, &count);
        bool left = string(align) == "LEFT";
        auto render = [&](const string &t) {
            string pad(width - t.size(), ' ');
            out += "*" + (left ? t + pad : pad + t) + "*\n";
        };
        string cur;
        for (int j = 0; j < count; j++) {
            const string &w = lines[idx++];
            string cand = cur.empty() ? w : cur + " " + w;
            // start a new line only when the next entry no longer fits
            if ((int)cand.size() > width) { render(cur); cur = w; }
            else cur = cand;
        }
        render(cur);
    }
    out += border + "\n";
    fwrite(out.data(), 1, out.size(), stdout);
}

import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) lines.add(line);
        String[] head = lines.get(0).trim().split("\\s+");
        int width = Integer.parseInt(head[0]), p = Integer.parseInt(head[1]);
        int idx = 1;
        String border = "*".repeat(width + 2);
        StringBuilder out = new StringBuilder(border).append('\n');
        for (int k = 0; k < p; k++) {
            String[] h = lines.get(idx++).trim().split("\\s+");
            boolean left = h[0].equals("LEFT");
            int count = Integer.parseInt(h[1]);
            String cur = "";
            for (int j = 0; j < count; j++) {
                String w = lines.get(idx++);
                String cand = cur.isEmpty() ? w : cur + " " + w;
                // start a new line only when the next entry no longer fits
                if (cand.length() > width) { render(out, cur, width, left); cur = w; }
                else cur = cand;
            }
            render(out, cur, width, left);
        }
        out.append(border).append('\n');
        System.out.print(out);
    }

    static void render(StringBuilder out, String t, int width, boolean left) {
        String pad = " ".repeat(width - t.length());
        out.append('*').append(left ? t + pad : pad + t).append("*\n");
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	var lines []string
	for sc.Scan() {
		lines = append(lines, strings.TrimSuffix(sc.Text(), "\r"))
	}
	var width, p int
	fmt.Sscan(lines[0], &width, &p)
	idx := 1
	border := strings.Repeat("*", width+2)
	var out strings.Builder
	out.WriteString(border + "\n")
	for k := 0; k < p; k++ {
		var align string
		var count int
		fmt.Sscan(lines[idx], &align, &count)
		idx++
		render := func(t string) {
			pad := strings.Repeat(" ", width-len(t))
			if align == "LEFT" {
				out.WriteString("*" + t + pad + "*\n")
			} else {
				out.WriteString("*" + pad + t + "*\n")
			}
		}
		cur := ""
		for j := 0; j < count; j++ {
			w := lines[idx]
			idx++
			cand := w
			if cur != "" {
				cand = cur + " " + w
			}
			// start a new line only when the next entry no longer fits
			if len(cand) > width {
				render(cur)
				cur = w
			} else {
				cur = cand
			}
		}
		render(cur)
	}
	out.WriteString(border + "\n")
	fmt.Print(out.String())
}
